const body = $input.first().json.body;
const entry = body.entry?.[0]?.changes?.[0]?.value;
const msg = entry?.messages?.[0];
if (!msg) return [];
const button_id = msg.interactive?.button_reply?.id || null;
const from = msg.from;
return [{ json: { button_id, from, raw_text: msg.text?.body || null } }];
